SELECT

FROM wms_monthly_bill b
LEFT JOIN sys_tenant t ON t.id = b.wms_tenant_id

    b.deleted = 0

        AND b.bill_month >= #{qo.billMonthStart}


        AND b.bill_month <= #{qo.billMonthEnd}


        AND b.wms_tenant_id = #{qo.wmsTenantId}


        AND b.status IN
        #{s}


ORDER BY b.bill_month DESC, b.wms_tenant_id ASC

SELECT COALESCE(SUM(monthly_fee), 0)
FROM wms_rack_assignment
WHERE wms_tenant_id = #{wmsTenantId}
  AND effective_from <= #{monthEnd}
  AND (effective_to IS NULL OR effective_to >= #{monthStart})

SELECT discount_pct FROM wms_tenant_rate_discount
WHERE wms_tenant_id = #{wmsTenantId}
ORDER BY id DESC LIMIT 1
